#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    unordered_set<ll> used;
    unordered_map<string, ll> nextCandidate;

    while (n--) {
        string line;
        getline(cin, line);

        size_t first = line.find('\'');
        size_t second = first == string::npos ? string::npos
                                              : line.find('\'', first + 1);

        string suffix;
        if (first == string::npos) {
            suffix = line;
        } else if (second == string::npos) {
            suffix = line.substr(first + 1);
        } else {
            suffix = line.substr(first + 1, second - first - 1);
        }

        ll value = stoll(suffix);
        ll mod = 1;
        for (size_t i = 0; i < suffix.size(); ++i)
            mod *= 10;

        ll candidate;
        auto it = nextCandidate.find(suffix);

        if (it != nextCandidate.end()) {
            candidate = it->second;
        } else {
            candidate = value;
            if (candidate < 1989)
                candidate += ((1989 - candidate + mod - 1) / mod) * mod;
        }

        while (used.count(candidate))
            candidate += mod;

        used.insert(candidate);
        nextCandidate[suffix] = candidate + mod;

        cout << candidate << '\n';
    }

    return 0;
}

