#include <iostream>
#include <cstring>
#include <unordered_set>
#include <cstdlib>
using namespace std;

using ll = long long;

char temp[3000000];
int n;
unordered_set<ll> used;

ll cal(ll len) {
    ll result = 1;
    while (len--) result *= 10;
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    for (int i = 0; i < n; ++i) {
        cin >> temp;

        char* ptr = strchr(temp, '\'');
        ++ptr;

        ll len = strlen(ptr);
        ll step = cal(len);
        ll limit = stoll(ptr);
        ll answer = limit;

        for (ll k = 1; k <= limit; ++k) {
            answer = k;
            do {
                answer += step;
            } while (answer < 1989 || !used.insert(answer).second);
        }

        cout << answer << '\n';
    }

    return 0;
}

